* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  background-color: #f5ede0;
  color: #3a2a1a;
  font-family: Georgia, "Times New Roman", Times, serif;
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: 640px;
  margin: 0 auto;
  padding: 32px 24px 24px;
}

.site-title {
  margin: 0 0 18px;
  font-size: 22px;
  font-weight: 700;
  color: #3a2a1a;
  letter-spacing: 0.2px;
}

.nav {
  padding-bottom: 18px;
  border-bottom: 1px solid #e2c89a;
}

.nav a {
  color: #a06a3c;
  text-decoration: none;
  margin-right: 18px;
  font-size: 16px;
}

.nav a:last-child {
  margin-right: 0;
}

main {
  padding-top: 36px;
  padding-bottom: 24px;
}

h1 {
  margin: 0 0 24px;
  font-size: 30px;
  font-weight: 700;
  color: #2a1d10;
  letter-spacing: 0.2px;
}

main p {
  margin: 0 0 16px;
  font-size: 16px;
  color: #3a2a1a;
}

main ul {
  margin: 0;
  padding-left: 22px;
  list-style-type: disc;
}

main ul li {
  margin-bottom: 12px;
  color: #3a2a1a;
  padding-left: 4px;
}

main ul li::marker {
  color: #3a2a1a;
}

.footer {
  border-top: 1px solid #e2c89a;
  padding-top: 16px;
  color: #b08a5a;
  font-size: 14px;
}

@media (max-width: 820px) {
  .container {
    max-width: 100%;
    padding: 32px 70px 24px;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 24px 17px 20px;
  }

  .site-title {
    font-size: 20px;
  }

  h1 {
    font-size: 26px;
  }

  .nav a {
    margin-right: 12px;
    font-size: 15px;
  }
}

